**Selenium Test with ALM Integration:**

```java
public class ALMEnabledTest {
    protected ALMConnector alm;
    protected String testRunId;
    protected String testSetId;

    @BeforeClass
    public void setupALM() {
        alm = new ALMConnector("http://almserver:8080/qcbin");
        alm.login("tester", "password");

        // Create test run in ALM
        testRunId = alm.createTestRun(
            "Nightly Regression",
            "Login Tests",
            System.getenv("BUILD_NUMBER")
        );
    }

    @Test
    public void testLogin() {
        WebDriver driver = new ChromeDriver();

        try {
            driver.get("https://test.app.com/login");

            // Get test data from ALM
            String username = alm.getTestParameter("username");
            String password = alm.getTestParameter("password");

            driver.findElement(By.id("username")).sendKeys(username);
            driver.findElement(By.id("password")).sendKeys(password);
            driver.findElement(By.id("login")).click();

            boolean success = driver.findElement(By.id("welcome")).isDisplayed();

            // Report to ALM
            if (success) {
                alm.updateTestRun(testRunId, "Passed", null);
            } else {
                File screenshot = ((TakesScreenshot) driver)
                    .getScreenshotAs(OutputType.FILE);
                alm.updateTestRun(testRunId, "Failed", screenshot);
            }

        } catch (Exception e) {
            alm.updateTestRun(testRunId, "Error", e.getMessage());
        } finally {
            driver.quit();
        }
    }

    @AfterClass
    public void cleanup() {
        alm.logout();
    }
}
```

