// Get parameters from ALM
public class ALMTestData {
    private ALMConnector alm;
    private String testSetId;

    public Map<String, String> getTestParameters() {
        Map<String, String> params = new HashMap<>();

        try {
            // Get test set details
            JSONObject testSet = alm.getTestSet(testSetId);
            JSONArray tests = testSet.getJSONArray("Tests");

            // Extract parameters for current test
            for (int i = 0; i < tests.length(); i++) {
                JSONObject test = tests.getJSONObject(i);
                if (test.getString("Name").equals(currentTest)) {
                    JSONArray testParams = test.getJSONArray("Parameters");
                    for (int j = 0; j < testParams.length(); j++) {
                        JSONObject param = testParams.getJSONObject(j);
                        params.put(
                            param.getString("Name"),
                            param.getString("Value")
                        );
                    }
                    break;
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return params;
    }

    // Data-driven testing
    public List<Map<String, String>> getTestDataRows() {
        List<Map<String, String>> dataRows = new ArrayList<>();

        try {
            // Get test data from ALM (Excel/CSV attachment)
            File testData = alm.getTestDataAttachment(testSetId);

            // Parse based on format
            if (testData.getName().endsWith(".xlsx")) {
                dataRows = parseExcel(testData);
            } else if (testData.getName().endsWith(".csv")) {
                dataRows = parseCSV(testData);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return dataRows;
    }
}
