**ALM to Selenium Trigger:**

```java
// ALM workflow script to trigger Selenium
Sub TestSet_BeforeRun
    ' Called when test set is about to run

    ' Get test set details
    testSetId = TestSet_Fields("CY_CYCLE_ID").Value

    ' Build parameters
    params = BuildParameterString()

    ' Trigger Jenkins job
    Call TriggerJenkinsJob("Selenium-Regression", params)

    ' Wait for completion
    Call WaitForJenkinsJob()

    ' Import results
    Call ImportSeleniumResults()
End Sub

Function TriggerJenkinsJob(jobName, params)
    Set http = CreateObject("MSXML2.ServerXMLHTTP")

    url = "http://jenkins:8080/job/" & jobName & "/buildWithParameters?" & params

    http.Open "POST", url, False
    http.SetRequestHeader "Authorization", "Basic " & EncodeBase64("user:token")
    http.Send

    TriggerJenkinsJob = (http.Status = 201)
End Function
```

**Selenium Test Class with ALM Trigger:**
```java
public class ALMTriggeredTest {

    public static void main(String[] args) {
        // Get parameters from environment (set by Jenkins)
        String testSetId = System.getenv("ALM_TEST_SET");
        String buildNumber = System.getenv("BUILD_NUMBER");

        // Connect to ALM
        ALMConnector alm = new ALMConnector("http://almserver:8080/qcbin");
        alm.login("selenium", System.getenv("ALM_PASS"));

        // Get tests to run
        List<String> tests = alm.getTestSetTests(testSetId);

        // Execute tests
        for (String test : tests) {
            Map<String, String> params = alm.getTestParameters(test);
            boolean passed = runTest(test, params);
            alm.reportResult(test, passed, buildNumber);
        }

        alm.logout();
    }
}
