**Automating the Pipeline:**

**1. Jenkins Plugin Installation**

```
Install ALM/QC Plugin in Jenkins:

1. Jenkins → Manage Jenkins → Manage Plugins
2. Available tab → Search "ALM" or "Quality Center"
3. Select "HP ALM/Quality Center Plugin"
4. Click "Install without restart"

Plugin Features:
├── Trigger ALM test sets
├── Upload results to ALM
├── Create defects on failure
├── Update test status
└── Notify ALM of build status
```

**2. Jenkins Pipeline Configuration**

```groovy
// Jenkinsfile with ALM integration
pipeline {
    agent any

    parameters {
        choice(
            name: 'TEST_SUITE',
            choices: ['Smoke', 'Regression', 'Full'],
            description: 'Test suite to run'
        )
        string(
            name: 'BUILD_VERSION',
            defaultValue: '2.5.1234',
            description: 'Build version to test'
        )
    }

    environment {
        ALM_URL = 'http://almserver:8080/qcbin'
        ALM_DOMAIN = 'DEFAULT'
        ALM_PROJECT = 'ECommerce'
        ALM_USER = credentials('alm-user')
    }

    stages {
        stage('Setup') {
            steps {
                echo "Testing build: ${params.BUILD_VERSION}"
                // Set up test environment
            }
        }

        stage('Trigger ALM Tests') {
            steps {
                almExecuteTestSet(
                    serverURL: env.ALM_URL,
                    username: env.ALM_USER,
                    password: env.ALM_USER_PSW,
                    domain: env.ALM_DOMAIN,
                    project: env.ALM_PROJECT,
                    testSetPath: "Root/${params.TEST_SUITE}",
                    runName: "Build ${params.BUILD_VERSION}",
                    parameters: [
                        [name: 'BuildVersion', value: params.BUILD_VERSION]
                    ]
                )
            }
        }

        stage('Wait for Results') {
            steps {
                script {
                    // Wait for test completion
                    def result = almWaitForCompletion(
                        testSetPath: "Root/${params.TEST_SUITE}"
                    )

                    if (result.status != 'Passed') {
                        currentBuild.result = 'UNSTABLE'
                    }
                }
            }
        }

        stage('Publish Results') {
            steps {
                // Publish test reports
                almPublishResults(
                    testSetPath: "Root/${params.TEST_SUITE}",
                    reportType: 'HTML'
                )
            }
        }
    }

    post {
        always {
            // Clean up
            echo 'Test execution complete'
        }
        failure {
            // Create defect in ALM
            almCreateDefect(
                summary: "Jenkins build failed: ${env.JOB_NAME} #${env.BUILD_NUMBER}",
                description: "Build failed. Check Jenkins logs.",
                severity: 'Critical',
                priority: 'Urgent'
            )
        }
    }
}
```

**3. Quality Gates**

```groovy
// Implement quality gates based on ALM results
stage('Quality Gate') {
    steps {
        script {
            // Get test results from ALM
            def results = almGetTestResults(
                testSetPath: "Root/${params.TEST_SUITE}"
            )

            // Define quality criteria
            def passRate = results.passed / results.total * 100
            def criticalDefects = results.criticalDefects

            echo "Pass rate: ${passRate}%"
            echo "Critical defects: ${criticalDefects}"

            // Quality gates
            if (passRate < 95) {
                error "Quality gate failed: Pass rate below 95%"
            }

            if (criticalDefects > 0) {
                error "Quality gate failed: Critical defects exist"
            }

            // Check requirements coverage
            def coverage = almGetCoverage(
                requirementFolder: "Root/Release_2.5"
            )

            if (coverage < 90) {
                echo "WARNING: Coverage below 90%"
            }
        }
    }
}
