**5. Automated Defect Creation**

```groovy
// Auto-create defects from test failures
stage('Process Failures') {
    steps {
        script {
            def failures = almGetFailedTests(
                testSetPath: "Root/${params.TEST_SUITE}"
            )

            failures.each { failure ->
                // Check if defect already exists
                def existing = almFindDefect(
                    testName: failure.testName,
                    buildVersion: params.BUILD_VERSION
                )

                if (!existing) {
                    // Create new defect
                    def defectId = almCreateDefect(
                        summary: "Test failure: ${failure.testName}",
                        description: failure.errorMessage,
                        severity: 'Major',
                        priority: 'High',
                        attachments: failure.screenshots,
                        linkedTest: failure.testId,
                        buildVersion: params.BUILD_VERSION
                    )

                    echo "Created defect: ${defectId}"
                }
            }
        }
    }
}
