**6. Cryptography and Hashing**

```javascript
// Generate HMAC signature
const CryptoJS = require('crypto-js');

const secret = pm.environment.get('apiSecret');
const timestamp = Date.now().toString();
const data = pm.request.url + timestamp;

const signature = CryptoJS.HmacSHA256(data, secret).toString();
pm.request.headers.add({
    key: 'X-Signature',
    value: signature
});
pm.request.headers.add({
    key: 'X-Timestamp',
    value: timestamp
});

// Base64 encoding
const credentials = `${username}:${password}`;
const encoded = CryptoJS.enc.Base64.stringify(CryptoJS.enc.Utf8.parse(credentials));
pm.request.headers.add({
    key: 'Authorization',
    value: `Basic ${encoded}`
});
```

