if (pm.info.iteration === pm.info.iterationCount) {
    const total = responseTimes.reduce((a,b) => a + b, 0);
    const avg = total / responseTimes.length;
    const max = Math.max(...responseTimes);
    const min = Math.min(...responseTimes);

    console.log('=== Performance Summary ===');
    console.log(`Iterations: ${responseTimes.length}`);
    console.log(`Average: ${avg.toFixed(2)}ms`);
    console.log(`Min: ${min}ms`);
    console.log(`Max: ${max}ms`);
    console.log(`95th percentile: ${calculatePercentile(responseTimes, 95)}ms`);
}

function calculatePercentile(arr, percentile) {
    const sorted = [...arr].sort((a,b) => a - b);
    const index = Math.ceil((percentile / 100) * sorted.length) - 1;
    return sorted[index];
}
