**5. Postman API for Automation**

```javascript
// Using Postman API to manage collections programmatically

const axios = require('axios');
const postmanApiKey = 'YOUR_API_KEY';
const baseUrl = 'https://api.getpostman.com';

// Get all collections
async function getCollections() {
    const response = await axios.get(`${baseUrl}/collections`, {
        headers: { 'X-Api-Key': postmanApiKey }
    });
    return response.data.collections;
}

// Create a collection
async function createCollection(name) {
    const collection = {
        collection: {
            info: {
                name: name,
                schema: 'https://schema.getpostman.com/json/collection/v2.1.0/collection.json'
            },
            item: []
        }
    };

    const response = await axios.post(`${baseUrl}/collections`, collection, {
        headers: { 'X-Api-Key': postmanApiKey }
    });
    return response.data;
}

// Run a collection via Postman API
async function runCollection(collectionUid, environmentUid) {
    const response = await axios.post(
        `${baseUrl}/runs`,
        {
            collection: collectionUid,
            environment: environmentUid
        },
        { headers: { 'X-Api-Key': postmanApiKey } }
    );
    return response.data;
}

// Example usage
async function main() {
    const collections = await getCollections();
    console.log('Collections:', collections);

    // Run a specific collection
    const run = await runCollection('123-abc-456', '789-def-012');
    console.log('Run started:', run);
}
