```javascript
// Common test patterns as functions

const TestHelpers = {
    // Test status code
    expectStatus: function(expectedCode) {
        pm.test(`Status code is ${expectedCode}`, () => {
            pm.expect(pm.response.code).to.equal(expectedCode);
        });
    },

