**5. Reusable Request Patterns**

```javascript
// Function to make authenticated requests
async function makeAuthenticatedRequest(method, endpoint, body = null) {
    const token = pm.environment.get('authToken');
    if (!token) {
        throw new Error('No auth token available');
    }

    const request = {
        url: pm.environment.get('baseUrl') + endpoint,
        method: method,
        header: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
        }
    };

    if (body) {
        request.body = {
            mode: 'raw',
            raw: JSON.stringify(body)
        };
    }

    return new Promise((resolve, reject) => {
        pm.sendRequest(request, function(err, res) {
            if (err) reject(err);
            else resolve(res);
        });
    });
}

// Usage
async function testWorkflow() {
    try {
        // Create user
        const createRes = await makeAuthenticatedRequest('POST', '/users', {
            name: 'Test User',
            email: 'test@example.com'
        });

        const userId = createRes.json().id;

        // Get user
        const getUserRes = await makeAuthenticatedRequest('GET', `/users/${userId}`);

        // Update user
        await makeAuthenticatedRequest('PUT', `/users/${userId}`, {
            name: 'Updated Name'
        });

        // Delete user
        await makeAuthenticatedRequest('DELETE', `/users/${userId}`);

        console.log('✅ Workflow completed successfully');
    } catch (error) {
        console.error('❌ Workflow failed:', error);
    }
}
