```javascript
// Common pattern for API Gateway testing

class APIGatewayClient {
    constructor(config) {
        this.baseUrl = config.baseUrl;
        this.apiKey = config.apiKey;
        this.region = config.region;
        this.stage = config.stage;
    }

    async request(method, path, data = null) {
        const url = `${this.baseUrl}/${this.stage}${path}`;

        const options = {
            url: url,
            method: method,
            header: {
                'Content-Type': 'application/json',
                'X-API-Key': this.apiKey
            }
        };

        if (data) {
            options.body = {
                mode: 'raw',
                raw: JSON.stringify(data)
            };
        }

        // Add cloud-specific auth
        if (this.region) {
            await this.addCloudAuth(options);
        }

        return new Promise((resolve, reject) => {
            pm.sendRequest(options, (err, res) => {
                if (err) reject(err);
                else resolve(res);
            });
        });
    }

    async addCloudAuth(options) {
        // Cloud-specific authentication
        switch (this.cloud) {
            case 'aws':
                await this.signAWS(options);
                break;
            case 'azure':
                options.header['Authorization'] = `Bearer ${pm.environment.get('azureToken')}`;
                break;
            case 'gcp':
                options.header['Authorization'] = `Bearer ${pm.environment.get('gcpToken')}`;
                break;
        }
    }
}

// Usage in tests
