// Create environment
async function createEnvironment(name, variables) {
    const environment = {
        environment: {
            name: name,
            values: Object.entries(variables).map(([key, value]) => ({
                key: key,
                value: value,
                enabled: true
            }))
        }
    };

    const response = await pm.sendRequest({
        url: `${POSTMAN_API}/environments`,
        method: 'POST',
        header: {
            'X-Api-Key': API_KEY,
            'Content-Type': 'application/json'
        },
        body: {
            mode: 'raw',
            raw: JSON.stringify(environment)
        }
    });

    return response.json();
}

// Update environment variables
async function updateEnvironment(envId, updates) {
    // First get current environment
    const current = await pm.sendRequest({
        url: `${POSTMAN_API}/environments/${envId}`,
        method: 'GET',
        header: {
            'X-Api-Key': API_KEY
        }
    });

    const env = current.json().environment;

    // Update values
    updates.forEach(update => {
        const existing = env.values.find(v => v.key === update.key);
        if (existing) {
            existing.value = update.value;
        } else {
            env.values.push({
                key: update.key,
                value: update.value,
                enabled: true
            });
        }
    });

    // Save updated environment
    const response = await pm.sendRequest({
        url: `${POSTMAN_API}/environments/${envId}`,
        method: 'PUT',
        header: {
            'X-Api-Key': API_KEY,
            'Content-Type': 'application/json'
        },
        body: {
            mode: 'raw',
            raw: JSON.stringify({ environment: env })
        }
    });

    return response.json();
}
