        iterations: 3,
        delay: 1000
    });

    console.log(`Run started: ${run.run.id}`);

    // Poll for results
    let completed = false;
    while (!completed) {
        await new Promise(r => setTimeout(r, 2000));
        const results = await getRunResults(run.run.id);

        if (results.run.status === 'completed') {
            completed = true;
            console.log('Run completed!');
            console.log(`Passed: ${results.run.stats.tests.passed}`);
            console.log(`Failed: ${results.run.stats.tests.failed}`);
        }
    }
}
