**7. Postman API Best Practices**

```javascript
// Rate limiting and error handling

class PostmanAPIClient {
    constructor(apiKey) {
        this.apiKey = apiKey;
        this.baseUrl = 'https://api.getpostman.com';
        this.rateLimit = {
            remaining: 100,
            reset: Date.now() + 3600000
        };
    }

    async request(method, path, data = null) {
        // Check rate limit
        if (this.rateLimit.remaining === 0) {
            const waitTime = this.rateLimit.reset - Date.now();
            if (waitTime > 0) {
                console.log(`Rate limit reached, waiting ${waitTime}ms`);
                await new Promise(r => setTimeout(r, waitTime));
            }
        }

        // Make request
        const options = {
            url: `${this.baseUrl}${path}`,
            method: method,
            header: {
                'X-Api-Key': this.apiKey,
                'Content-Type': 'application/json'
            }
        };

        if (data) {
            options.body = {
                mode: 'raw',
                raw: JSON.stringify(data)
            };
        }

        const response = await pm.sendRequest(options);

        // Update rate limit
        const remaining = response.headers.get('X-RateLimit-Remaining');
        const reset = response.headers.get('X-RateLimit-Reset');

        if (remaining) {
            this.rateLimit.remaining = parseInt(remaining);
            this.rateLimit.reset = parseInt(reset) * 1000;
        }

        // Handle errors
        if (response.code >= 400) {
            throw new Error(`API error: ${response.code} - ${response.text()}`);
        }

        return response.json();
    }

    async retry(method, path, data = null, maxRetries = 3) {
        for (let i = 0; i < maxRetries; i++) {
            try {
                return await this.request(method, path, data);
            } catch (error) {
                if (i === maxRetries - 1) throw error;
                console.log(`Retry ${i + 1}/${maxRetries} after error: ${error.message}`);
                await new Promise(r => setTimeout(r, 1000 * Math.pow(2, i)));
            }
        }
    }
}
