**5. Monitoring and Alerting**

```javascript
// Comprehensive monitoring setup

class IntegrationMonitor {
    constructor() {
        this.metrics = {
            builds: [],
            tests: [],
            deployments: []
        };
    }

    recordBuild(buildInfo) {
        this.metrics.builds.push({
            ...buildInfo,
            timestamp: new Date()
        });
    }

    recordTestRun(testInfo) {
        this.metrics.tests.push({
            ...testInfo,
            timestamp: new Date()
        });
    }

    getHealthStatus() {
        const last24h = Date.now() - 86400000;
        const recentTests = this.metrics.tests.filter(t => 
            t.timestamp > last24h
        );

        const passed = recentTests.filter(t => t.passed).length;
        const total = recentTests.length;

        return {
            passRate: total ? (passed / total * 100).toFixed(2) : 100,
            totalTests: total,
            avgResponseTime: this.calculateAvgResponse(recentTests),
            deployments: this.metrics.deployments.length,
            status: this.determineStatus(passed, total)
        };
    }

    alertIfNeeded() {
        const health = this.getHealthStatus();

        if (health.passRate < 90) {
            this.sendAlert({
                severity: 'high',
                message: `Test pass rate dropped to ${health.passRate}%`
            });
        }

        if (health.avgResponseTime > 2000) {
            this.sendAlert({
                severity: 'medium',
                message: `High response time: ${health.avgResponseTime}ms`
            });
        }
    }
}
