**4. Newman Programmatic Usage**

```javascript
// run-tests.js - Programmatic Newman execution
const newman = require('newman');
const fs = require('fs');
const path = require('path');

// Configuration
const config = {
    collection: './collections/api-tests.postman_collection.json',
    environment: './environments/staging.postman_environment.json',
    data: './data/test-data.csv',
    iterations: 3,
    reporters: ['cli', 'json', 'junit', 'htmlextra']
};

// Run tests
newman.run({
    collection: require(config.collection),
    environment: require(config.environment),
    iterationData: config.data,
    iterationCount: config.iterations,
    reporters: config.reporters,
    reporter: {
        json: { export: './reports/results.json' },
        junit: { export: './reports/junit.xml' },
        htmlextra: { export: './reports/report.html' }
    },
    timeoutRequest: 10000,
    delayRequest: 1000
}, function(err, summary) {
    if (err) {
        console.error('❌ Newman run failed:', err);
        process.exit(1);
    }

    // Parse results
    const totalTests = summary.run.stats.tests.total;
    const passedTests = summary.run.stats.tests.passed;
    const failedTests = summary.run.stats.tests.failed;
    const passRate = (passedTests / totalTests * 100).toFixed(2);

    console.log('\n📊 TEST SUMMARY');
    console.log('══════════════════════════════');
    console.log(`Total Tests: ${totalTests}`);
    console.log(`✅ Passed: ${passedTests}`);
    console.log(`❌ Failed: ${failedTests}`);
    console.log(`📈 Pass Rate: ${passRate}%`);
    console.log(`⏱️  Total Time: ${summary.run.timings.completed - summary.run.timings.started}ms`);

    // List failures
    if (summary.run.failures.length > 0) {
        console.log('\n❌ FAILURES');
        console.log('══════════════════════════════');
        summary.run.failures.forEach((failure, index) => {
            console.log(`${index + 1}. ${failure.error.test}: ${failure.error.message}`);
            console.log(`   Request: ${failure.source.name}`);
        });
    }

    // Determine exit code
    if (failedTests > 0) {
        process.exit(1);
    } else {
        console.log('\n✅ All tests passed!');
        process.exit(0);
    }
});
