// Thread Group Calculator - Use to plan your tests

function calculateLoad(threads, rampUp, loops, samplersPerLoop) {
    const totalRequests = threads * loops * samplersPerLoop;
    const usersPerSecond = threads / rampUp;
    const estimatedDuration = rampUp + (loops * (samplersPerLoop * 2)); // assumes 2 sec per request

