**6. JSR223 Assertion: Complex Validation**

```groovy
// Advanced response validation
import groovy.json.JsonSlurper

def response = prev.getResponseDataAsString()
def success = true
def message = ""

// Check response time
if (prev.getTime() > 5000) {
    success = false
    message += "Response time ${prev.getTime()}ms exceeds 5000ms. "
}

// Parse and validate JSON
try {
    def json = new JsonSlurper().parseText(response)

    // Validate required fields
    def required = ["id", "status", "data"]
    def missing = required.findAll { !json.containsKey(it) }
    if (missing) {
        success = false
        message += "Missing fields: ${missing}. "
    }

    // Validate data integrity
    if (json.data?.items) {
        json.data.items.eachWithIndex { item, idx ->
            if (item.price < 0) {
                success = false
                message += "Item ${idx} has negative price. "
            }
        }
    }

} catch (Exception e) {
    success = false
    message += "Invalid JSON: ${e.message}"
}

// Set assertion result
if (!success) {
    AssertionResult.setFailure(true)
    AssertionResult.setFailureMessage(message)
}
