// Load and apply thresholds
stage('Apply Thresholds') {
    steps {
        script {
            def thresholds = readYaml file: 'performance-thresholds.yaml'
            def envThresholds = thresholds[params.ENVIRONMENT]

            def metrics = parseJTL('results.jtl')

            // Apply thresholds
            if (metrics.avgResponseTime > envThresholds.response_time.critical) {
                error "Response time ${metrics.avgResponseTime}ms exceeds critical threshold ${envThresholds.response_time.critical}ms"
            } else if (metrics.avgResponseTime > envThresholds.response_time.warning) {
                unstable "Response time ${metrics.avgResponseTime}ms exceeds warning threshold ${envThresholds.response_time.warning}ms"
            }

            if (metrics.errorRate > envThresholds.error_rate.critical) {
                error "Error rate ${metrics.errorRate}% exceeds critical threshold ${envThresholds.error_rate.critical}%"
            } else if (metrics.errorRate > envThresholds.error_rate.warning) {
                unstable "Error rate ${metrics.errorRate}% exceeds warning threshold ${envThresholds.error_rate.warning}%"
            }

            if (metrics.throughput < envThresholds.throughput.min) {
                unstable "Throughput ${metrics.throughput}/sec below minimum ${envThresholds.throughput.min}/sec"
            }
        }
    }
}
